from __future__ import annotations

import json

import pytest

from llm_router import LLMRouter, Model, Provider, RouterProfile
from tests.llm_router.support.fault_server import (
    ScriptedHTTPServer,
    ScriptedResponse,
)
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_success_response,
)
from tests.llm_router.support.workers.worker_patches import patched_openai_sdk

pytestmark = pytest.mark.verification_kind("unit")

_CHAT_PATH = openai_chat_path()

_EXPECTED = {"item": "pallet jack", "quantity": 3}

_SCHEMA = {
    "type": "object",
    "properties": {
        "item": {"type": "string"},
        "quantity": {"type": "integer"},
    },
    "required": ["item", "quantity"],
    "additionalProperties": False,
}


def _run(monkeypatch, texts, schema):
    value = "assurance-value"
    monkeypatch.setenv("OPENROUTER_API_KEY_1", value)
    replies = [
        ScriptedResponse(
            status_code=200,
            headers={"Content-Type": "application/json"},
            body=openai_success_response(text=text),
        )
        for text in texts
    ]
    with (
        ScriptedHTTPServer(
            port=0, routes={("POST", _CHAT_PATH): replies}
        ) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
    ):
        router = LLMRouter(
            RouterProfile(model=Model.DEEPSEEK_V3, provider=Provider.OPENROUTER),
            temperature=0.0,
        )
        response = router.query("Describe the record.", response_schema=schema)
        recorded = server.recorded_requests("POST", _CHAT_PATH)
    return response, recorded


@pytest.mark.verifies("REQ_STRUCTURED_TEXT_OUTPUT[revision==2]")
def test_fenced_reply_parsed_first_time(monkeypatch: pytest.MonkeyPatch) -> None:
    """A fenced string reply yields the object without a repair turn."""
    fenced = f"Here:\n```json\n{json.dumps(_EXPECTED)}\n```"
    response, recorded = _run(monkeypatch, [fenced], _SCHEMA)
    assert response.data["parsed"] == _EXPECTED
    assert len(recorded) == 1


@pytest.mark.verifies("REQ_STRUCTURED_TEXT_OUTPUT[revision==2]")
def test_json_string_wrapped_object(monkeypatch: pytest.MonkeyPatch) -> None:
    """A valid-JSON-string wrapper around an object is unwrapped."""
    response, recorded = _run(monkeypatch, ['"{}"'], {"type": "object"})
    assert response.data["parsed"] == {}
    assert len(recorded) == 1


@pytest.mark.verifies("REQ_STRUCTURED_TEXT_OUTPUT[revision==2]")
def test_keys_and_nulls_preserved(monkeypatch: pytest.MonkeyPatch) -> None:
    """Key case, whitespace and null values are kept exactly."""
    expected = {"UserName": "ada", " Key ": None, "itemCount": 3}
    schema = {
        "type": "object",
        "properties": {
            "UserName": {"type": "string"},
            " Key ": {"type": ["integer", "null"]},
            "itemCount": {"type": "integer"},
        },
        "required": ["UserName", " Key ", "itemCount"],
        "additionalProperties": False,
    }
    response, _ = _run(monkeypatch, [json.dumps(expected)], schema)
    assert response.data["parsed"] == expected
    assert list(response.data["parsed"]) == list(expected)


@pytest.mark.verifies("REQ_STRUCTURED_TEXT_OUTPUT[revision==2]")
def test_single_item_array_rejected(monkeypatch: pytest.MonkeyPatch) -> None:
    """A one-item array is rejected as non-object and repaired."""
    texts = [json.dumps([_EXPECTED]), json.dumps(_EXPECTED)]
    response, recorded = _run(monkeypatch, texts, _SCHEMA)
    assert response.data["parsed"] == _EXPECTED
    assert len(recorded) == 2
    assert "Structured output must be a JSON object." in recorded[1].body.decode()


@pytest.mark.verifies("REQ_STRUCTURED_TEXT_OUTPUT[revision==2]")
def test_invalid_json_reported(monkeypatch: pytest.MonkeyPatch) -> None:
    """A non-JSON reply is reported as invalid JSON in the repair turn."""
    texts = ["the shelf has three", json.dumps(_EXPECTED)]
    response, recorded = _run(monkeypatch, texts, _SCHEMA)
    assert response.data["parsed"] == _EXPECTED
    assert len(recorded) == 2
    assert "Structured output is not valid JSON" in recorded[1].body.decode()
